162→type Rule = {
163→  id: string;
164→  name: string;
165→  zone: string | null;
166→  zipCodes: string | null;
167→  minOrderAmount: number | null;
168→  deliveryFee: number | null;
169→  freeShippingAbove: number | null;
170→  estimatedDays: string | null;
171→  cutoffTime: string | null;
172→  daysOfWeek: string | null;
173→  isActive: boolean;
174→  priority: number;
175→};
